query:
mutation reportDeleteRun ( $accountId:ID! $reportDeleteRunInput:ReportDeleteRunInput!) {
	report ( accountId:$accountId ) {
		deleteRun ( input:$reportDeleteRunInput  )  {
			run {
				id
				reportConfigurationId
				reportName
				templateName
				runAt
				status
				trigger
				failureReason
				renderingFormat
				downloadLink {
					url
					expiresAt
				}
			}
		}
	}	
}
